argv:
$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-active-16pm-n1.mjs'
try{
[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log(JSON.stringify({error:'hard_timeout'}));process.exit(0)},6000);
try{const v=await(await fetch('http://127.0.0.1:17447/json/version')).json();const ws=new WebSocket(v.webSocketDebuggerUrl);
ws.addEventListener('open',()=>ws.send(JSON.stringify({id:1,method:'Target.activateTarget',params:{targetId:'B025E9E07C7426B014912EF6ABB37AB5'}})),{once:true});
ws.addEventListener('message',e=>{const z=JSON.parse(e.data);if(z.id===1){console.log(JSON.stringify({activated:!!z.result,error:z.error?.message||null}));process.exit(0)}});
ws.addEventListener('error',()=>{console.log('{"error":"WS"}');process.exit(0)},{once:true});
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,90)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false))
& node.exe $tmp
}finally{Remove-Item $tmp -Force -ErrorAction SilentlyContinue}
